def is_prime_sum_pair(n: int) -> tuple[int, int] | None:
    """Return a pair of primes summing to the even integer n, or None."""
    if n <= 2 or n % 2 != 0:
        return None

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    for i in range(2, n // 2 + 1):
        if is_prime(i) and is_prime(n - i):
            return (i, n - i)

    return None
